import java.util.concurrent.atomic.AtomicReference
import java.util.concurrent.atomic.LongAdder

final class AccountStore(private val state: AtomicReference[Map[String, Long]]):
  def transfer(from: String, to: String, amt: Long): Boolean =
    @tailrec
    def attempt(): Boolean =
      val cur = state.get()                       // immutable snapshot: O(1) to read
      if (cur.getOrElse(from, 0L) < amt) false
      else {
        val next = cur.updated(from, cur(from) - amt).updated(to, cur.getOrElse(to, 0L) + amt)
        if (state.compareAndSet(cur, next)) true else attempt()   // retry: value semantics make retry free
      }
    attempt()

private val hits = new LongAdder()      // striped: no cache-line ping-pong under contention
